// ── UploadProgress ────────────────────────────────────────────────────────

describe('UploadProgress', () => {
  it('defaults to 0 when no arguments', () => {
    expect(new UploadProgress().progressPercent).toBe(0);
  });

  it('rounds to percent when only value is provided', () => {
    expect(new UploadProgress(73.6).progressPercent).toBe(74);
  });

  it('computes percent from value and range', () => {
    expect(new UploadProgress(1, 4).progressPercent).toBe(25);
  });

  it('innerData sets data and forces progressPercent to 100', () => {
    const progress = new UploadProgress(50, 100);
    const result = progress.innerData({ key: 'value' });
    expect(result.progressPercent).toBe(100);
    expect(result.data).toEqual({ key: 'value' });
  });
});

// ── DownloadBlob ──────────────────────────────────────────────────────────

describe('DownloadBlob', () => {
  it('stores data and name', () => {
    const blob = new Blob(['hello']);
    const dl = new DownloadBlob(blob, 'file.txt');
    expect(dl.data).toBe(blob);
    expect(dl.name).toBe('file.txt');
  });
});
